    //  circle packing https://editor.p5js.org/abachman/sketches/98OgeRBjU
const INITIAL = 4;
const SPAWN_FRAMES = 8;
const GROW = 1;
const DRAW = "circles";
const ALLOW_INSIDE = true;

const circles = [];

function addCircle(existing) {
  let tries = 10;

  let c = {
    x: sketch.random(sketch.width),
    y: sketch.random(sketch.height),
    r: 2,
    growing: true,
    neighbors: [],
  };
  if (ALLOW_INSIDE) {
    c.touching = overlap(c);
  } else {
    c.touching = inside(c);
  }
    
  while (tries > 0 && existing.some(c.touching)) {
    c.x = sketch.random(sketch.width);
    c.y = sketch.random(sketch.height);
    tries--;
  }

  if (tries > 0) {
    existing.push(c);
    return true;
  }
}

function inside(c) {
  return function (other) {
    return other !== c && sketch.dist(c.x, c.y, other.x, other.y) < c.r + other.r;
  };
}

function overlap(c) {
  const margin = GROW * 3
  return function (other) {
    if (other === c) {
      return false
    }
    const dc = sketch.dist(c.x, c.y, other.x, other.y);
    if (dc < c.r + other.r) { // inside
      return other.growing || sketch.abs(other.r  - (dc + c.r)) < margin
    } else { // outside
      return sketch.abs(other.r - (dc - c.r)) < margin
    }
  }
}

function grow(cs) {
  cs.forEach((c) => {
    if (c.growing) {
      c.r += GROW;
      let touched;
      if ((touched = cs.find(c.touching))) {
        c.r -= 1;
        c.growing = false;
        c.col = sketch.color(sketch.random(360), 60, 90);

        touched.neighbors.push(c);
        c.neighbors.push(touched);
      }
    }
  });
}

function display(cs) {
  if (DRAW == "circles") {
    cs.forEach((c) => {
      sketch.fill(c.growing ? 220 : c.col);
      sketch.ellipse(c.x, c.y, c.r * 2);
    });
  } else if (DRAW == "lines") {
    cs.forEach((c) => {
      c.neighbors.forEach((n) => {
        if (c.col) {
          sketch.stroke(c.col);
          sketch.line(c.x, c.y, n.x, n.y);
        }
      });
    });
  }
}

