    //  color wheeling, genuary 17 https://editor.p5js.org/abachman/sketches/dRXT5CdFy
const ROWS = 160;
const STEP = 5;

// color wheel separation
// 120 - triadic
// 20 - monochromatic
const SEP = 90;
const SATS = [60, 70, 80]
const BRITS = [60, 70, 90]

const PALETTE = [];
const LINE_COLORS = [];

let btn;

sketch.setup = function() {
  sketch.createCanvas(400, 400);
  sketch.colorMode(sketch.HSB);

  gen();

  btn = sketch.createButton("RECOLOR");
  btn.addClass("button-50");
  btn.mouseClicked(gen);
}

function gen() {
  const root = sketch.floor(sketch.random(360)),
    s = shuff(SATS),
    b = shuff(BRITS);

  while (PALETTE.length > 0) PALETTE.pop();
  while (LINE_COLORS.length > 0) LINE_COLORS.pop();

  for (let i = 0; i < 3; i++) {
    PALETTE.push(sketch.color((root + SEP * i) % 360, s[i], b[i]));
  }

  for (let n = 0; n < ROWS; n++) {
    LINE_COLORS.push(PALETTE[sketch.floor(sketch.random(PALETTE.length))]);
  }
}

function shuff(array) {
  const rand = array.map(() => sketch.random());
  return array.sort(function (a, b) {
    return rand[a] - rand[b];
  });
}

sketch.draw = function() {
  sketch.background(0);
  sketch.noFill();
  const high = STEP * 3;

  let ay = 0;
  for (let n = 0; n < ROWS; n++) {
    const nz = sketch.noise(n * 0.005, sketch.frameCount * 0.02);
    const th = STEP * 2 * nz;

    ay += th;

    sketch.stroke(LINE_COLORS[n]);
    sketch.strokeWeight(th);

    elps(ay);

    ay += th - 1;
  }

  sketch.stroke(16);
  sketch.strokeWeight(2);
  const sz = 16;
  
  for (let x = 0; x < 3; x++) {
    sketch.fill(PALETTE[x]);
    sketch.rect(10 + (x * (sz + 4)), sketch.height - (sz + 10), sz);
  }
}

function vert(ay) {
  sketch.line(ay, -2, ay, sketch.height + 2);
}

function horiz(ay) {
  sketch.line(-2, ay, sketch.width + 2, ay);
}

function elps(ay) {
  sketch.ellipse(sketch.width / 2, sketch.height / 2, ay);
}

 
