/* ------------------======================------------------
 * circle-packing.js
 * ------------------======================------------------ */

function addCircle(existing) {
  let tries = 10;

  let c = {
    x: sketch.random(sketch.width),
    y: sketch.random(sketch.height),
    r: 2,
    growing: true,
    neighbors: [],
  };
  if (ALLOW_INSIDE) {
    c.touching = overlap(c);
  } else {
    c.touching = inside(c);
  }
    
  while (tries > 0 && existing.some(c.touching)) {
    c.x = sketch.random(sketch.width);
    c.y = sketch.random(sketch.height);
    tries--;
  }

  if (tries > 0) {
    existing.push(c);
    return true;
  }
}

function inside(c) {
  return function (other) {
    return other !== c && sketch.dist(c.x, c.y, other.x, other.y) < c.r + other.r;
  };
}

function overlap(c) {
  const margin = GROW * 3
  return function (other) {
    if (other === c) {
      return false
    }
    const dc = sketch.dist(c.x, c.y, other.x, other.y);
    if (dc < c.r + other.r) { // inside
      return other.growing || sketch.abs(other.r  - (dc + c.r)) < margin
    } else { // outside
      return sketch.abs(other.r - (dc - c.r)) < margin
    }
  }
}

function grow(cs) {
  cs.forEach((c) => {
    if (c.growing) {
      c.r += GROW;
      let touched;
      if ((touched = cs.find(c.touching))) {
        c.r -= 1;
        c.growing = false;
        c.col = sketch.color(sketch.random(360), 60, 90);

        touched.neighbors.push(c);
        c.neighbors.push(touched);
      }
    }
  });
}

function display(cs, g) {
  if (DRAW == "circles") {
    cs.forEach((c) => {
      g.ellipse(c.x, c.y, c.r * 2);
    });
  } else if (DRAW == "lines") {
    cs.forEach((c) => {
      c.neighbors.forEach((n) => {
        if (c.col) {
          g.stroke(c.col);
          g.line(c.x, c.y, n.x, n.y);
        }
      });
    });
  }
}

/* ------------------======================------------------
 * line-drawing.js
 * ------------------======================------------------ */
function rot() {
  if (SCATTER.rot) {
    return sketch.random(ROT);
  } else {
    return ROT;
  }
}

function border() {
  const b = BORDER,
    hb = BORDER / 2;
  sketch.strokeWeight(b);
  sketch.stroke(0);
  sketch.rect(hb, hb, sketch.width - b, sketch.height - b);
}

function scolor() {
  if (SCATTER.color) {
    const [h, s, b] = COLOR;
    sketch.stroke(h, s, b, 0.2);
    COLOR[0] += 0.1;
  } else {
    sketch.stroke(...COLOR, 30);
  }
}

function xoff() {
  return SCATTER.x ? sketch.random(sketch.width) + sketch.height * XOFF : XOFF;
}

function yoff() {
  return SCATTER.y ? sketch.random(sketch.height) + sketch.height * YOFF : YOFF;
}

 
