class Tree {
  constructor(qt, g) {
    this.nodes = [];
    this.qt = qt;
    this.g = g;
    this.seeds = [];
  }

  seed(particle) {
    this.seeds.push(particle);
    this.add(particle, gen);
  }

  add(particle, gen) {
    if (particle.treed) return;

    particle.treed = true;
    particle.gen = gen;
    this.nodes.push(particle);

    // this.g.fill(0, 100, 250, 130);
    // for (let node of this.nodes) {
    //   this.g.ellipse(particle.x, particle.y, SIZE - 2);
    // }
  }

  update(gen) {
    let nexts = [],
      node;
    for (let n = 0; n < this.nodes.length; n++) {
      node = this.nodes[n];
      if (gen - node.gen > AGEOUT) continue;
      if (node.seeded > 2) continue;

      const parts = this.qt.retrieve(node);
      for (let part of parts) {
        if (!part.alive) continue;
        const d = sketch.dist(node.x, node.y, part.x, part.y);
        if (d < SIZE) {
          // track hit relationship
          node.children.push(part);

          nexts.push(part);
          part.alive = false;
          node.seeded++;
        }
      }
    }

    for (let particle of nexts) {
      this.add(particle, gen);
    }
  }

  display() {
    let node;
    // for (let n = 0; n < this.nodes.length; n++) {
    //   node = this.nodes[n];
    //   fill(node.gen % 360, 100, 100);
    //   ellipse(node.x, node.y, SIZE);
    // }
    for (let n = 0; n < this.seeds.length; n++) {
      node = this.seeds[n];
      node.displayRecurse();
    }
  }
}

class Particle extends Quadtree.Circle {
  constructor(p) {
    super({
      x: p.x,
      y: p.y,
      r: SIZE / 2,
    });
    this.alive = true;
    this.seeded = 0;
    this.treed = false;
    this.gen = 0;
    this.children = [];
  }

  update() {
    if (this.alive) {
      const v = p5.Vector.random2D();
      v.mult(SPEED);

      // this.p.add(v);
      this.x = sketch.constrain(this.x + v.x, 0, sketch.width);
      this.y = sketch.constrain(this.y + v.y, 0, sketch.height);
    }
  }

  display() {
    if (this.alive) {
      sketch.ellipse(this.x, this.y, SIZE);
    }
  }

  displayRecurse(level = 0) {
    // fill((level * 2) % 360, 100, 100);
    // ellipse(this.x, this.y, SIZE);

    // image(daisy, this.x, this.y, 16, 16);

    sketch.stroke((level * 2) % 360, 0, 100 - level);

    if (this.children.length > 0) {
      this.children.forEach((child) => {
        sketch.line(this.x, this.y, child.x, child.y);

        child.displayRecurse(level + 1);
      });
    }
  }
}

 
