function drawRing(x, y) {
  sketch.noFill();

  sketch.translate(x, y)

  const r = 100
  const nudgeR = 0
  const nudgeT = 1
  let t = 0

  for (let i = 0; i < segs.length; i++) {
    // curve (cx1, cy1, x1, y1, x2, y2, cx2, cy2)
    let nt = t + segs[i]

    const args = [
      (r + nudgeR) * sketch.cos(t - nudgeT),
      (r + nudgeR) * sketch.sin(t - nudgeT),
      r * sketch.cos(t),
      r * sketch.sin(t),
      r * sketch.cos(nt),
      r * sketch.sin(nt),
      (r + nudgeR) * sketch.cos(nt + nudgeT),
      (r + nudgeR) * sketch.sin(nt + nudgeT),
    ]

    sketch.stroke(cols[i])
    sketch.curve(...args)

    // line(x1, y1, x2, y2)

    t = t + segs[i]
  }
}

