function separate(points) {
  const ls = [];
  let i = 0;
  let letter = [];
  let avg = 0,
    sum = 0,
    counted = 0;

  while (i < points.length) {
    const curr = points[i];
    letter.push(curr);

    if (i < points.length - 1) {
      const next = points[i + 1];
      const gap = sketch.dist(curr.x, curr.y, next.x, next.y);

      if (counted > 10 && gap > avg * GFACT) {
        // pinch off a letter, don't update sum avg & counted
        ls.push(letter);
        letter = [];
      } else {
        // update sum avg & counted
        sum += gap;
        counted++;
        avg = sum / counted;
      }
    }
    i++;
  }

  ls.push(letter);
  return ls;
}

