class Panel {
  constructor(x, y, w, h, graphic) {
    Object.assign(this, { x, y, w, h, graphic });
    this.image = sketch.createGraphics(this.w, this.h);
  }

  update() {
    // copy pixels of graphic sliced by this panel's dimensions
    this.image.copy(
      this.graphic,
      this.x,
      this.y,
      this.w,
      this.h,
      0,
      0,
      this.w,
      this.h
    );
    if (DO_BLUR) {
      this.image.filter(sketch.BLUR, 4);
    }
  }

  draw() {
    // draws a slice of the image
    sketch.image(this.image, this.x, this.y);

    sketch.stroke(60);
    sketch.strokeWeight(6);

    sketch.noFill();
    sketch.rect(this.x, this.y, this.w, this.h);
  }
}

