sketch.setup = function() {
  sketch.createCanvas(600, 600)
  sketch.background(0)
  sketch.stroke(255)
  sketch.strokeWeight(2)
  sketch.fill(0)
}

function LayerFlower(n, a, r) {
  // x = r cos(t)
  // y = r sin(t)

  /*
    [
      r (a + Cos[n t])/(a + 1) {
          Cos[t + b Sin[2 n t]],
          Sin[t + b Sin[2 n t]]
      }, {t, 0, 2 Pi}
    ],
  */

  let period = 75
  let points = n * period
  let step = sketch.TWO_PI / points

  let lfo = 0
  let lfos = sketch.TWO_PI / period
  let x, y
  let lx = null,
    ly
  let fx, fy
  sketch.beginShape()
  for (let t = 0; t < sketch.TWO_PI; t += step) {
    let offset = sketch.sin(lfo) * 40
    let rad = r / 2 + offset
    x = rad * sketch.cos(t)
    y = rad * sketch.sin(t)

    if (lx === null) {
      fx = x
      fy = y
    } else {
      // line(lx, ly, x, y)
    }
    sketch.vertex(x, y)

    lx = x
    ly = y
    lfo += lfos
  }

  // line(lx, ly, fx, fy)
  sketch.vertex(fx, fy)
  sketch.endShape()
}

function LayerDisk(_n, _a, r) {
  sketch.circle(0, 0, r)
}

function LayerSpots(n, a, r) {
  let crad = sketch.random(a, a * 2)

  sketch.push()
  for (let i = 0; i < n; i++) {
    sketch.rotate(sketch.TWO_PI / n)
    sketch.circle(0, r / 2, crad)
  }
  sketch.pop()
}

