  for (let r = sketch.width - 30; r > step / 2; r -= step) {
    // LayerDisk(0, 0, r)
    // LayerSpots(int(random(7, 17)), random(8, 16), r)

    const f = sketch.random([LayerDisk, LayerSpots, LayerFlower])
    f(sketch.int(sketch.random(13, 27)), sketch.random(8, 16), r)
  }

  sketch.noLoop()
