let points = []
const noiseScale = 800

sketch.setup = function() {
  sketch.createCanvas(1200, 800);
  sketch.strokeWeight(4);
  sketch.smooth()
  sketch.background(0)
  sketch.stroke(255, 30)
  sketch.fill(255)

  for (let i = 0; i < 250; i++) {
    points.push(new Particle(sketch.random(sketch.width), sketch.random(sketch.height)))
  }
}

