sketch.draw = function() {
  // background(0); // comment out this line to draw paths

  points.forEach(function(p) {
    p.move()
    p.display()
    p.checkEdge()
  })
  
  /* if (frameCount > 1800 && !saved) {
    saveCanvas();
    saved = true;
  } */
}

class Particle {
  constructor(x, y) {
    this.pos = sketch.createVector(x, y)
    this.dir = sketch.createVector(0, 0)
    this.vel = sketch.createVector(0, 0)
    this.color = [sketch.random(100, 255), sketch.random(255), sketch.random(255)]
    this.speed = 0.4
  }

  move() {
    let angle = sketch.noise(this.pos.x / noiseScale, this.pos.y / noiseScale) * 
        sketch.TWO_PI * noiseScale;
    this.dir.x = sketch.cos(angle);
    this.dir.y = sketch.sin(angle);
    this.vel = this.dir.copy();
    this.vel.mult(this.speed);
    this.pos.add(this.vel);
  }

  display() {
    sketch.stroke(this.color[0], this.color[1], this.color[2])
    // stroke(this.color)
    sketch.point(this.pos.x, this.pos.y)
  }

  checkEdge() {
    if (this.pos.x > sketch.width || this.pos.x < 0 || this.pos.y > sketch.height || this.pos.y < 0) {
      this.pos = sketch.createVector(sketch.random(sketch.width), sketch.random(sketch.height))
      this.color = [sketch.random(255), sketch.random(255), sketch.random(255)] 
    }
  }
}
 
