/* ------------------======================------------------
 * boundary.js
 * ------------------======================------------------ */
  class Boundary {
    constructor(x1, y1, x2, y2) {
      this.a = sketch.createVector(x1, y1)
      this.b = sketch.createVector(x2, y2)
    }

    show() {
      sketch.stroke(255)
      sketch.line(
        this.a.x,
        this.a.y,
        this.b.x,
        this.b.y
      )
    }
  }
/* ------------------======================------------------
 * ray.js
 * ------------------======================------------------ */
class Ray {
  constructor(pos, angle) {
    this.pos = pos
    this.dir = p5.Vector.fromAngle(angle)
  }

  lookAt(x, y) {
    this.dir.x = x - this.pos.x
    this.dir.y = y - this.pos.y
    this.dir.normalize()
  }

  show() {
    sketch.stroke(255, 50)

    sketch.push() // start changing geometry
    sketch.translate(this.pos.x, this.pos.y)
    sketch.line(0, 0, this.dir.x * 1000, this.dir.y * 1000)
    sketch.pop() // change geometry back
  }

  cast(wall) {
    // learn math!
    // line-line intersection

    const x1 = wall.a.x;
    const y1 = wall.a.y;
    const x2 = wall.b.x;
    const y2 = wall.b.y;
    const x3 = this.pos.x;
    const y3 = this.pos.y;
    const x4 = this.pos.x + this.dir.x;
    const y4 = this.pos.y + this.dir.y;

    const denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if (denom == 0) {
      return
    }

    const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom
    const u = - ((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom
    if (t > 0 && t < 1 && u > 0) {
      const pt = sketch.createVector()
      pt.x = x1 + t * (x2 - x1)
      pt.y = y1 + t * (y2 - y1)
      return pt
    } else {
      return
    }
  }
}
 
