function generate(seed, scale, colr) {
  sketch.randomSeed(seed);

  const comps = [];
  const offs = [];
  const rs = [];

  for (let i = 0; i < CCOUNT; i++) {
    comps.push(sketch.ceil(sketch.random(3, SPIKEY)));
    offs.push(sketch.random(5));
  }

  for (let i = 0; i < COUNT + 1; i++) {
    const components = comps.map((factor, c) => {
      return (
        (scale / 7) * sketch.sin(sketch.map(i, 0, COUNT, offs[c], offs[c] + factor * sketch.TWO_PI))
      );
    });
    rs.push(scale + components.reduce((sum, val) => sum + val));
  }

  sketch.strokeWeight(2);

  let times = 2, // ceil(random(2, 5)),
    t = 0,
    nc = colr,
    drop = sketch.random(4, 10);
  do {
    sketch.stroke(nc);
    sketch.beginShape();
    for (let i = 0; i < COUNT + 1; i++) {
      const r = rs[i];
      const t = sketch.map(i, 0, COUNT, 0, sketch.TWO_PI);
      const x = r * sketch.cos(t);
      const y = r * sketch.sin(t);
      sketch.vertex(x, y);
    }
    sketch.endShape();
    t++;

    sketch.strokeWeight(1);
    nc = sketch.color(sketch.red(nc), sketch.green(nc), sketch.blue(nc), 100 - t * 10);
    if (sketch.random() > 0.5) {
      sketch.translate(0, drop);
    } else {
      sketch.translate(drop, 0);
    }
  } while (t < times);
}

 
