// sol lewitt 

//
// `COUNT` people gather in an empty lot
// each carries one can of paint
//   they paint the spot they are standing on
//   they turn in a random direction
//   they step forward
// repeat until 
//   everyone has left the field or
//   `STEPS` steps have been taken
// 


const COUNT = 100
const STEPS = 5000
const SPD = [1.2, 3]
const HUE = [0, 20]
const SAT = [40, 70]
const BRT = [80, 100]
const TRN = 0.5

function j(l) { return l.map(v => v.toString()).join('_') }
function name(step) {
  return `sol-lewitt--${step}-${COUNT}-${j(SPD)}-${j(HUE)}-${j(SAT)}-${j(BRT)}`
}


class Person {
  constructor(w, h) {
    this.w = w
    this.h = h
    
    this.x = sketch.random(w) 
    this.y = sketch.random(h)
    this.d = sketch.random(sketch.TWO_PI)
    this.s = sketch.random(1.2, 3)
    
    this.c = sketch.color(
      sketch.random(...HUE), 
      sketch.random(...SAT),
      sketch.random(...BRT),
      TRN
    )
    
    this.left = false
  }
  
  paint() {
    sketch.fill(this.c)
    sketch.ellipse(this.x, this.y, 4)
  }
  
  turn() {
    this.d += sketch.random(sketch.TWO_PI)
  }
  
  step() {
    this.x += this.s * sketch.cos(this.d)
    this.y += this.s * sketch.sin(this.d)
    
    if (this.x < 0 || this.x > this.w || this.y < 0 || this.y > this.h) {
      this.left = true
    }
  }
}

